{
  "source_id": "TEXT",
  "cast": [
    {
      "id": "P01",
      "name": "格雷戈尔·萨姆沙"
    },
    {
      "id": "P02",
      "name": "母亲"
    },
    {
      "id": "P03",
      "name": "父亲"
    },
    {
      "id": "P04",
      "name": "妹妹"
    }
  ],
  "locations": [
    {
      "id": "L01",
      "name": "卧室及门外"
    }
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P04"
      ],
      "flow": [
        {
          "action": "格雷戈尔仰躺在床上，看见自己变成虫形躯体。"
        },
        {
          "speaker": "P01",
          "line": "我出什么事了？",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "action": "他看见细弱的腿在眼前颤动。"
        },
        {
          "action": "他望向墙上金色镜框里的皮草女士画。"
        },
        {
          "action": "他看见桌上摊开的商品样品。"
        },
        {
          "action": "他望向窗口，铁皮窗檐上滴着雨。"
        },
        {
          "speaker": "P01",
          "line": "再睡一会儿，也许就能忘掉这一切。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "action": "他用力翻身，却摇摇晃晃地转回仰卧。"
        },
        {
          "action": "他闭上眼，反复翻身。"
        },
        {
          "action": "他停止翻身，腰侧微微抽搐。"
        },
        {
          "speaker": "P01",
          "line": "这份差事真把人累坏了。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "speaker": "P01",
          "line": "别的推销员，像皇后一样过着生活。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "action": "他抬起腿碰了肚子上的白色小点，又立刻缩回。"
        },
        {
          "action": "他蹭到床柱旁，又滑回原处。"
        },
        {
          "speaker": "P01",
          "line": "若不是为了父母，我早该辞职了。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "speaker": "P01",
          "line": "只要替父母还清老板的债，就有转机。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "action": "他看向柜子上滴答作响的闹钟。"
        },
        {
          "speaker": "P01",
          "line": "火车五点就开了，一切都来不及了。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "speaker": "P01",
          "line": "请病假吗？五年没病，太可疑了。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "speaker": "P01",
          "line": "老板会带着医生来，怪罪我父母。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "speaker": "P01",
          "line": "可我现在特别饿，身体倒还好。",
          "mode": "spoken",
          "delivery": "对房间说"
        },
        {
          "action": "母亲在门边轻敲，声音柔和。"
        },
        {
          "speaker": "P02",
          "line": "格雷戈尔，六点三刻了，你不是还得赶火车吗？",
          "mode": "spoken"
        },
        {
          "action": "他开口时，声音里混入尖锐的杂音。"
        },
        {
          "speaker": "P01",
          "line": "是的，是的，谢谢妈妈，我这就起床。",
          "mode": "spoken"
        },
        {
          "action": "母亲走开。"
        },
        {
          "action": "门外的脚步声停顿了一下。"
        },
        {
          "action": "父亲用拳头轻敲另一扇门。"
        },
        {
          "speaker": "P03",
          "line": "格雷戈尔！格雷戈尔！",
          "mode": "spoken"
        },
        {
          "speaker": "P03",
          "line": "你怎么啦？",
          "mode": "spoken"
        },
        {
          "action": "妹妹在另一侧门边轻声说话。"
        },
        {
          "speaker": "P04",
          "line": "你是不是不舒服？需要什么吗？",
          "mode": "spoken"
        },
        {
          "speaker": "P01",
          "line": "我这就好了。",
          "mode": "spoken"
        },
        {
          "action": "父亲转身离开去吃早餐。"
        },
        {
          "speaker": "P04",
          "line": "格雷戈尔，开开门，我求你了。",
          "mode": "spoken"
        },
        {
          "action": "格雷戈尔没有开门，只盯着锁着的门。"
        }
      ]
    }
  ]
}

